import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators, AbstractControl, ValidationErrors } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService, Korisnik } from "../../services/auth.service";

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent {
  public imagePath: string = 'assets/administar.jpg';
  public registerForm: FormGroup;
  public alertMessage: string = '';
  public alertType: 'success' | 'error' = 'error';
  public showModal: boolean = false;
  public today: string = '';

  get ime() { return this.registerForm.get('ime'); }
  get prezime() { return this.registerForm.get('prezime'); }
  get email() { return this.registerForm.get('email'); }
  get lozinka() { return this.registerForm.get('lozinka'); }
  get datumRodjenja() { return this.registerForm.get('datumRodjenja'); }

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private authService: AuthService
  ) {
    const danas = new Date();
    danas.setDate(danas.getDate() - 1); // maksimalan datum je juče
    this.today = danas.toISOString().split('T')[0];

    this.registerForm = this.fb.group({
      ime: ['', Validators.required],
      prezime: ['', Validators.required],
      email: [
        '',
        [
          Validators.required,
          Validators.email,
          Validators.pattern(/^[a-zA-Z0-9._%+-]+@gmail\.com$/) // samo gmail.com
        ]
      ],
      lozinka: [
        '',
        [
          Validators.required,
          Validators.minLength(8),
          Validators.pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\W).{8,}$/)
        ]
      ],
      rola: ['CITIZEN', Validators.required],
      datumRodjenja: ['', [Validators.required, this.pastDateValidator]]
    });
  }

  private pastDateValidator(control: AbstractControl): ValidationErrors | null {
    const value = control.value;
    if (!value) return null;
    const inputDate = new Date(value);
    const danas = new Date();
    if (inputDate >= danas) {
      return { futureDate: true };
    }
    return null;
  }

  public goToLogin(): void {
    this.router.navigate(['/login']);
  }

  private showAlert(message: string, type: 'success' | 'error' = 'error') {
    this.alertMessage = message;
    this.alertType = type;
    this.showModal = true;
  }

  public handleModalClose() {
    this.showModal = false;
    if (this.alertType === 'success') {
      this.router.navigate(['/login']);
    }
  }

  public onSubmit(): void {
    const imeCtrl = this.registerForm.get('ime');
    const prezimeCtrl = this.registerForm.get('prezime');
    const emailCtrl = this.registerForm.get('email');
    const lozinkaCtrl = this.registerForm.get('lozinka');
    const datumCtrl = this.registerForm.get('datumRodjenja');

    if (!imeCtrl?.value || !prezimeCtrl?.value || !emailCtrl?.value || !lozinkaCtrl?.value || !datumCtrl?.value) {
      this.showAlert('Molimo popunite sva polja.', 'error');
      return;
    }

    if (datumCtrl.invalid) {
      if (datumCtrl.errors?.['futureDate']) {
        this.showAlert('Datum rođenja mora biti u prošlosti.', 'error');
        return;
      }
    }

    if (emailCtrl.invalid) {
      if (emailCtrl.errors?.['email'] || emailCtrl.errors?.['pattern']) {
        this.showAlert('Email mora biti u formatu @gmail.com.', 'error');
        return;
      }
    }

    if (lozinkaCtrl.invalid) {
      if (lozinkaCtrl.errors?.['minlength']) {
        this.showAlert('Lozinka mora imati najmanje 8 karaktera.', 'error');
        return;
      }
      if (lozinkaCtrl.errors?.['pattern']) {
        this.showAlert('Lozinka mora sadržati veliko slovo, malo slovo i specijalan znak.', 'error');
        return;
      }
    }

    if (this.registerForm.valid) {
      const korisnikData: Korisnik = this.registerForm.value;
      this.authService.register(korisnikData).subscribe({
        next: () => this.showAlert('Registracija uspešna!', 'success'),
        error: (error) => this.showAlert(error.error || 'Došlo je do greške pri registraciji.', 'error')
      });
    }
  }
}
<app-custom-alert
  *ngIf="showModal"
  [message]="alertMessage"
  [type]="alertType"
  (closed)="handleModalClose()">
</app-custom-alert>

<section class="vh-100 signup-section">
  <div class="container h-100">
    <div class="row d-flex justify-content-center align-items-center h-100">
      <div class="col-lg-12 col-xl-11">
        <div class="card signup-card">
          <div class="row g-0 h-100">

            <div class="col-md-6 d-flex justify-content-center align-items-center">
              <div class="p-4 p-md-5 form-container-padding w-100">
                <p class="text-center h1 fw-bold mb-4">Registracija</p>
                <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">

                  <div class="mb-4">
                    <label for="ime" class="form-label">Ime</label>
                    <input id="ime" type="text" class="form-control" formControlName="ime" placeholder="Unesite vas ime">
                    <div class="text-danger mt-1" *ngIf="ime?.touched && ime?.hasError('required')">
                      Ime je obavezno.
                    </div>
                  </div>

                  <div class="mb-4">
                    <label for="prezime" class="form-label">Prezime</label>
                    <input id="prezime" type="text" class="form-control" formControlName="prezime" placeholder="Unesite vas prezime">
                    <div class="text-danger mt-1" *ngIf="prezime?.touched && prezime?.hasError('required')">
                      Prezime je obavezno.
                    </div>
                  </div>

                  <div class="mb-4">
                    <label for="datumRodjenja" class="form-label">Datum rođenja</label>
                    <input id="datumRodjenja" type="date" class="form-control" formControlName="datumRodjenja" max="{{ today }}">
                    <div class="text-danger mt-1" *ngIf="datumRodjenja?.touched && datumRodjenja?.invalid">
                      <span *ngIf="datumRodjenja?.hasError('required')">Datum rođenja je obavezan.</span>
                      <span *ngIf="datumRodjenja?.hasError('futureDate')">Datum rođenja mora biti u prošlosti.</span>
                    </div>
                  </div>

                  <div class="mb-4">
                    <label for="email" class="form-label">Email</label>
                    <input id="email" type="email" class="form-control" formControlName="email" placeholder="Unesite vas email">
                    <div class="text-danger mt-1" *ngIf="email?.touched">
                      <span *ngIf="email?.hasError('required')">Email je obavezan.</span>
                      <span *ngIf="email?.hasError('email') || email?.hasError('pattern')">Email mora biti u formatu @gmail.com.</span>
                    </div>
                  </div>

                  <div class="mb-4">
                    <label for="lozinka" class="form-label">Sifra</label>
                    <input id="lozinka" type="password" class="form-control" formControlName="lozinka" placeholder="Unesite vasu sifru">
                    <div class="text-danger mt-1" *ngIf="lozinka?.touched">
                      <span *ngIf="lozinka?.hasError('required')">Lozinka je obavezna.</span>
                      <span *ngIf="lozinka?.hasError('minlength')">Lozinka mora imati najmanje 8 karaktera.</span>
                      <span *ngIf="lozinka?.hasError('pattern')">Lozinka mora sadržati veliko slovo, malo slovo i specijalan znak.</span>
                    </div>
                  </div>

                  <div class="mb-4">
                    <label for="grad" class="form-label">Grad</label>
                    <input id="grad" type="text" class="form-control" formControlName="grad" placeholder="Unesite grad">
                    <div class="text-danger mt-1" *ngIf="grad?.touched && grad?.hasError('required')">
                      Grad je obavezan.
                    </div>
                  </div>

                  <div class="mb-4">
                    <label for="adresa" class="form-label">Adresa</label>
                    <input id="adresa" type="text" class="form-control" formControlName="adresa" placeholder="Unesite adresu">
                    <div class="text-danger mt-1" *ngIf="adresa?.touched && adresa?.hasError('required')">
                      Adresa je obavezna.
                    </div>
                  </div>


                  <button type="submit" class="btn btn-dark w-100" [disabled]="!registerForm.valid">
                    Registracija
                  </button>

                  <p class="text-center mt-3">
                    Vec imas nalog?
                    <a  class="login-link" (click)="goToLogin()">Uloguj se</a>
                  </p>
                </form>
              </div>
            </div>

            <div class="col-md-6 d-none d-md-block">
              <img [src]="imagePath" alt="Signup image" class="signup-image">
            </div>

          </div>
        </div>
      </div>
    </div>
  </div>
</section>
